#!/bin/sh
# Build the busycoq halting proof of 1RB0LE_1RC1RB_1LD0RA_1LA1LC_0LC0LF_0RB--- (bbchallenge 67137).
# usage: sh build.sh /path/to/busycoq
#   (a checkout of the BB6 branch of https://github.com/ccz181078/busycoq, tested at 33209bc: the proof uses its
#   Individual62.v)
# Needs Coq 8.18 or later (tested with 8.18.0). About 12 hours, nearly all of it the final evaluation run_ok.
# H67137.v is generated by tools/coq/t4engine/proof/build.sh; this script only compiles it. The file ends with
# Print Assumptions halt.
set -e
BC=${1:?give the path of a busycoq checkout (BB6 branch)}
HERE=$(cd "$(dirname "$0")" && pwd)
V="$BC/verify"
cp "$HERE"/H67137.v "$V"/
cd "$V"
[ -f Makefile.coq ] || make Makefile.coq > /dev/null
make -f Makefile.coq Individual62.vo > /dev/null 2>&1
t0=$(date +%s)
coqc -Q . BusyCoq H67137.v
echo "compiled in $(( $(date +%s) - t0 )) s"
